// JSON is authoritative. Default: check generated files; --write: regenerate them.
import assert from 'node:assert/strict';
import {readFileSync,writeFileSync,existsSync} from 'node:fs';
import {createHash} from 'node:crypto';
const root=new URL('../',import.meta.url),read=p=>readFileSync(new URL(p,root),'utf8');
const catalog=JSON.parse(read('docs/third-party/catalog.json')),schema=JSON.parse(read('docs/third-party/catalog.schema.json'));
// Validate every schema keyword used by this catalog, without installing a runtime dependency.
function validate(v,s,path='$'){
 if(s.$ref)return validate(v,schema.$defs[s.$ref.split('/').at(-1)],path);
 if(s.enum)assert.ok(s.enum.includes(v),path+': enum');
 if(s.type){const types=Array.isArray(s.type)?s.type:[s.type];assert.ok(types.some(t=>t==='null'?v===null:t==='array'?Array.isArray(v):t==='integer'?Number.isInteger(v):t==='object'?v!==null&&typeof v==='object'&&!Array.isArray(v):typeof v===t),path+': type');}
 if(s.pattern&&typeof v==='string')assert.match(v,new RegExp(s.pattern),path);
 if(Array.isArray(v)){if(s.minItems)assert.ok(v.length>=s.minItems,path);v.forEach((x,i)=>validate(x,s.items,path+'['+i+']'));}
 else if(v&&typeof v==='object'){
  for(const key of s.required??[])assert.ok(Object.hasOwn(v,key),path+': missing '+key);
  for(const [key,value]of Object.entries(v)){if(s.additionalProperties===false)assert.ok(Object.hasOwn(s.properties,key),path+': unknown '+key);if(s.properties?.[key])validate(value,s.properties[key],path+'.'+key);}
 }
}
validate(catalog,schema);
const project=catalog.projectSourceLicense,projectLicense=read(project.licenseFile);
assert.ok(project.distributionFile.startsWith('dist/'),'Project license must be shipped in dist/');
const publicLicensePath=project.distributionFile.slice(5);
const ids=new Set();
for(const entry of [...catalog.entries,...catalog.references]){assert.ok(!ids.has(entry.id),'Duplicate ID '+entry.id);ids.add(entry.id);}
for(const entry of catalog.entries){
 for(const path of [...entry.files,...entry.notices])assert.ok(existsSync(new URL(path,root)),entry.id+': missing '+path);
 if(entry.category==='runtime'||entry.relationship==='adapted')assert.ok(entry.notices.length,entry.id+': notice required');
}
for(const notice of catalog.noticeSnapshots)assert.equal(createHash('sha256').update(readFileSync(new URL(notice.path,root))).digest('hex'),notice.sha256,notice.path);
const inventories=Object.fromEntries(Object.entries(catalog.inventoryFiles).map(([key,path])=>[key,JSON.parse(read(path))]));
const html=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const md=s=>String(s).replaceAll('|','\\|').replaceAll('\n',' ');
// The coding agents used to write the app are named in the app's own section, not only in the tool list.
const agents=catalog.entries.filter(e=>e.relationship==='coding-agent').map(e=>e.name),agentNotice='コードの作成・修正・検証には、AI コーディングエージェント（'+agents.join('、')+'）を使用しています。';
const groups=[['reference','参考にした実装・移植したコード'],['runtime','配信に含まれる実行基盤'],['tool','学習・検証・制作・配信ツール']];
const distribution={reference:'実装を参照',wasm:'WASM に組み込み','runtime-files':'JS / WASM を配信','development-only':'開発時に利用'};
const license=e=>e.licenseExpression===null?'提供元の利用条件':e.licenseExpression==='LicenseRef-SplitMix64-Public-Domain'?'Public domain（利用許諾付き）':e.licenseExpression==='CC0-1.0 AND LicenseRef-Bryc-Public-Domain'?'Public domain / CC0':e.licenseExpression==='LicenseRef-KataGo-Neural-Network'?'MIT型（ネット用）':e.licenseExpression;
const markdown=['<!-- Generated by node tools/third-party.mjs --write. Edit docs/third-party/catalog.json and LICENSE. -->','# 参考ソフトウェアと第三者ライセンス',
 `自作ソースコードのライセンスは [${project.licenseExpression}](${project.licenseFile}) です。適用範囲：${project.scope}`,
 agentNotice,
 `正本は [catalog.json](docs/third-party/catalog.json)、形式は [JSON Schema](docs/third-party/catalog.schema.json) です。確認日：${catalog.checkedOn}。${catalog.scope}`,
 '配信用の表示は [ライセンスと参考ソフトウェア](dist/credits.html)、配信用 JSON は [third-party-catalog.json](dist/third-party-catalog.json) です。'];
const sections=[`<section><h2>アプリのソースコード</h2><p>自作ソースコードのライセンスは <a href="${html(publicLicensePath)}">${html(project.licenseExpression)}（全文）</a>です。</p><p>${html(project.scope)}</p><p>${html(agentNotice)}</p><p>WASM や生成 JS に含まれる第三者コードにも、以下のライセンスと告知が適用されます。</p></section>`];
for(const [key,title]of groups){
 markdown.push('## '+title);
 const table=['| ソフトウェア | 利用形態・ライセンス | 用途・変更点・告知 |','| --- | --- | --- |'];
 const items=catalog.entries.filter(e=>e.category===key);
 for(const e of items){const links=e.notices.map(p=>`[${p.split('/').at(-1)}](${p})`).join('、');table.push(`| [${md(e.name)}${e.version?' '+md(e.version):''}](${e.urls[0]}) | ${distribution[e.distribution]} / ${md(license(e))} | ${md(e.usage)} ${e.modifications.map(md).join(' ')} ${e.copyrightNotices.map(md).join(' / ')} ${links} |`);}
 markdown.push(table.join('\n'));
 sections.push(`<section><h2>${html(title)}</h2><ul>${items.map(e=>`<li><strong>${html(e.name)}${e.version?' '+html(e.version):''}</strong><p>${html(e.usage)} ${html(e.modifications.join(' '))}</p><p>${distribution[e.distribution]}。ライセンス：${html(license(e))}。${e.notices.map(p=>` <a href="${html(p.startsWith('dist/')?p.slice(5):catalog.repository+'/blob/main/'+p)}">${html(p.split('/').at(-1))}</a>`).join('')}</p>${e.copyrightNotices.map(n=>`<p>${html(n)}</p>`).join('')}<p>${e.urls.map((u,i)=>`<a href="${html(u)}">出典 ${i+1}</a>`).join(' / ')}</p></li>`).join('')}</ul></section>`);
}
markdown.push('## 推移依存と手法の一次資料',`[Node 依存目録](${catalog.inventoryFiles.node}) は ${inventories.node.packages.length} 件、[Python 環境目録](${catalog.inventoryFiles.python}) は ${inventories.python.packages.length} 件です。版・ライセンス・ロックファイルの SHA-256 を記録しています。`,...catalog.references.map(r=>`- ${r.authors}, [${r.title} (${r.year})](${r.url})：${r.usage}`),'## 更新と検証',
 '自作ソースコードのライセンス本文はルートの LICENSE、適用範囲と配信先は catalog.json の projectSourceLicense で管理します。配信用の本文は正本からコピーし、第三者目録や告知とは分けて検証します。WASM や生成 JS に含まれる第三者コードの告知も維持します。',
 '参考実装・ツール・文献は catalog.json を編集します。依存を更新した場合は下のコマンドで Node / Python の目録を取得し、catalog.json の版・告知・noticeSnapshots も確認して更新します。生成ファイルの手編集は行いません。Python の目録は実行した環境の依存を記録します。CPU 環境の場合は --extra cuda を省略します。',
 '`prepare.mjs` は固定版の ONNX LICENSE / ThirdPartyNotices をローカルからコピーします。WASM のビルドでは使った Rust 配布物の包括告知と各ライセンスを保存します。最小 Rust 環境では `rustup component add rust-docs` が必要です。',
 '```sh\nnode tools/ai-gnn/inventory-node.mjs\nuv run --project tools/ai-gnn --extra cuda python tools/ai-gnn/inventory_python.py\nnode tools/third-party.mjs --write\nnode tools/third-party.mjs\nnode tools/check-third-party.mjs --prepared\n```');
const page='<!doctype html>\n<html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ライセンスと参考ソフトウェア — 曲面囲碁</title><style>body{font:1rem/1.8 system-ui,sans-serif;max-width:52rem;margin:2rem auto;padding:0 1rem;color:#183333;background:#fafaf5}a{color:#126161}h1{font-size:1.7rem}h2{font-size:1.2rem;margin-top:2rem}li{margin:1.2rem 0}li p{margin:.3rem 0}</style></head><body><main>\n<!-- Generated from docs/third-party/catalog.json. -->\n<p><a href="./">曲面囲碁へ戻る</a></p><h1>ライセンスと参考ソフトウェア</h1><p>確認日：'+html(catalog.checkedOn)+'。<a href="third-party-catalog.json">機械可読の目録（JSON）</a>。<a href="'+html(catalog.repository+'/blob/main/THIRD_PARTY.md')+'">ソースリポジトリの目録</a>。</p>'+sections.join('\n')+'<section><h2>手法の一次資料</h2><ul>'+catalog.references.map(r=>`<li>${html(r.authors)}: <a href="${html(r.url)}">${html(r.title)} (${r.year})</a> — ${html(r.usage)}</li>`).join('')+'</ul></section>'+'</main></body></html>\n';
const outputs={
 [project.distributionFile]:projectLicense,
 'THIRD_PARTY.md':markdown.join('\n\n')+'\n',
 'dist/credits.html':page,
 'dist/third-party-catalog.json':JSON.stringify({...catalog,$schema:'../docs/third-party/catalog.schema.json',resolvedInventories:inventories},null,2)+'\n',
 'dist/licenses/sources.json':JSON.stringify({schemaVersion:1,checkedOn:catalog.checkedOn,versions:{onnxruntime:catalog.entries.find(e=>e.id==='onnxruntime-web').version},condition:'Generated from docs/third-party/catalog.json. Full upstream notices and implementation attributions are retained.',notices:catalog.noticeSnapshots.map(n=>({...n,path:n.path.slice('dist/licenses/'.length)}))},null,2)+'\n'
};
// Published JSON embeds the inventories and omits the repository-only editor schema pointer.
const publicData=JSON.parse(outputs['dist/third-party-catalog.json']);delete publicData.$schema;outputs['dist/third-party-catalog.json']=JSON.stringify(publicData,null,2)+'\n';
for(const [path,text]of Object.entries(outputs))if(process.argv.includes('--write'))writeFileSync(new URL(path,root),text);else assert.equal(read(path),text,'Regenerate '+path+' with node tools/third-party.mjs --write');
console.log('Third-party catalog: schema, '+catalog.entries.length+' software entries, '+catalog.references.length+' references and '+Object.keys(outputs).length+' generated files '+(process.argv.includes('--write')?'written.':'checked.'));
